int main() {
    long long a, b, c, l;
    cin >> a >> b >> c >> l;

    // We need to count the number of triples (da, db, dc) such that:
    // 0 <= da, db, dc (integers)
    // da + db + dc <= l
    // and (a+da), (b+db), (c+dc) can form a non-degenerate triangle.
    // Non-degenerate triangle condition: sum of any two sides > third side.
    // Let x = a+da, y = b+db, z = c+dc.
    // Conditions: x+y>z, x+z>y, y+z>x.

    // Total number of ways to distribute at most l among 3 sticks:
    // This is C(l+3, 3) = (l+3)(l+2)(l+1)/6.
    // But we need to subtract the cases where triangle inequality fails.

    // Triangle inequality fails if one side >= sum of other two.
    // Since we're dealing with positive integers, degenerate means one side == sum of other two.
    // But non-degenerate means strictly greater. So we fail if x+y<=z OR x+z<=y OR y+z<=x.

    // Let's count the complement: cases where triangle inequality is violated.
    // Violation happens when:
    // Case 1: a+da + b+db <= c+dc
    // Case 2: a+da + c+dc <= b+db
    // Case 3: b+db + c+dc <= a+da

    // These three cases are mutually exclusive? Let's check.
    // If a+da + b+db <= c+dc and a+da + c+dc <= b+db, then adding: 2(a+da) + b+db + c+dc <= b+db + c+dc => 2(a+da) <= 0, impossible since a+da >= 1.
    // So the three cases are mutually exclusive.

    // So we can count each case separately and sum them up.

    // For Case 1: a+da + b+db <= c+dc
    // Let da' = da, db' = db, dc' = dc.
    // a + da' + b + db' <= c + dc'
    // da' + db' - dc' <= c - a - b
    // Let k = c - a - b.
    // We need da' + db' - dc' <= k, with da'+db'+dc' <= l, da',db',dc' >= 0.

    // This is a bit complex. Let me think of another approach.

    // Alternative: iterate over possible values? l can be up to 3*10^5, so O(l^2) might be too slow.
    // We need an O(1) or O(l) solution.

    // Let's use the inclusion-exclusion or direct counting.

    // Total ways = C(l+3, 3) = (l+1)(l+2)(l+3)/6

    // Now subtract bad cases.

    // For a given case, say a+da + b+db <= c+dc:
    // Let s = da + db + dc <= l
    // And a + da + b + db <= c + dc
    // => da + db - dc <= c - a - b
    // Let t = c - a - b
    // da + db - dc <= t
    // Also da + db + dc <= l

    // Let u = da + db, v = dc. Then u - v <= t and u + v <= l, u >= 0, v >= 0.
    // For fixed u and v, the number of (da, db) with da+db=u is u+1.
    // So we need to sum over valid (u,v) of (u+1).

    // Constraints:
    // u - v <= t  => v >= u - t
    // u + v <= l  => v <= l - u
    // v >= 0
    // u >= 0

    // So for each u >= 0, v ranges from max(0, u-t) to min(l-u, ...) but also v <= l-u.
    // And we need max(0, u-t) <= min(l-u, ...) actually just v from max(0, u-t) to l-u, provided max(0, u-t) <= l-u.

    // But u can be at most l (since v>=0, u+v<=l).

    // So sum over u=0 to l:
    //   lower = max(0, u - t)
    //   upper = l - u
    //   if lower <= upper:
    //       count += (upper - lower + 1) * (u + 1)

    // This is O(l) per case, and we have 3 cases, so O(l) total. l up to 3*10^5, this should be fine.

    long long total = (l + 1) * (l + 2) * (l + 3) / 6;

    long long bad = 0;

    // Case 1: a+da + b+db <= c+dc
    // t1 = c - a - b
    long long t1 = c - a - b;
    for (long long u = 0; u <= l; u++) {
        long long lower = max(0LL, u - t1);
        long long upper = l - u;
        if (lower <= upper) {
            bad += (upper - lower + 1) * (u + 1);
        }
    }

    // Case 2: a+da + c+dc <= b+db
    // t2 = b - a - c
    long long t2 = b - a - c;
    for (long long u = 0; u <= l; u++) {
        long long lower = max(0LL, u - t2);
        long long upper = l - u;
        if (lower <= upper) {
            bad += (upper - lower + 1) * (u + 1);
        }
    }

    // Case 3: b+db + c+dc <= a+da
    // t3 = a - b - c
    long long t3 = a - b - c;
    for (long long u = 0; u <= l; u++) {
        long long lower = max(0LL, u - t3);
        long long upper = l - u;
        if (lower <= upper) {
            bad += (upper - lower + 1) * (u + 1);
        }
    }

    long long result = total - bad;
    cout << result << endl;

    return 0;
}
