    // So bad = sum_{u=0}^{l} (u+1) * max(0, v_high - v_low + 1)
    // where v_low = max(0, u-D), v_high = l-u.

    // But l can be up to 3*10^5, so we can iterate over u.

    long long D = z - x - y;
    long long total = (l + 1) * (l + 2) * (l + 3) / 6;
    long long bad = 0;

    for (long long u = 0; u <= l; u++) {
        long long v_low = max(0LL, u - D);
        long long v_high = l - u;
        if (v_low <= v_high) {
