        long long max_s = (l - k) / 2;
        if (max_s < 0) return 0;

        for (long long s = 0; s <= max_s; s++) {
            long long min_x = max(0LL, k + s);
            long long max_x = l - s;
            if (min_x > max_x) continue;
            long long count_x = max_x - min_x + 1;
            long long count_yz = s + 1;
            total += count_x * count_yz;
        }
        return total;
