    long long bad1 = count_bad(b + c - a); // a+x >= b+y+c+z
    long long bad2 = count_bad(a + c - b); // b+y >= a+x+c+z
    long long bad3 = count_bad(a + b - c); // c+z >= a+x+b+y

    long long total_bad = bad1 + bad2 + bad3;

    // Total number of ways to distribute at most l among 3 sticks:
    // Number of non-negative integer solutions to x+y+z <= l is C(l+3, 3).
    long long total_ways = (l + 1) * (l + 2) * (l + 3) / 6;

    long long answer = total_ways - total_bad;

    cout << answer << endl;

    return 0;
}
