    // Bad case 1: a+da >= b+db + c+dc
    // Bad case 2: b+db >= a+da + c+dc
    // Bad case 3: c+dc >= a+da + b+db

    // Let's compute the count for bad case 1.
    // a + da >= b + db + c + dc
    // da - db - dc >= b + c - a
    // Let R1 = b + c - a.
    // We need da >= R1 + db + dc, with da + db + dc <= l, da,db,dc >= 0.

    // If R1 + db + dc > l, no solution for this (db,dc).
    // da ranges from max(0, R1 + db + dc) to l - db - dc.
    // Number of da values = max(0, l - db - dc - (R1 + db + dc) + 1) = max(0, l - R1 - 2*db - 2*dc + 1)
    // This is positive only if 2*db + 2*dc <= l - R1.
    // Let S = l - R1. If S < 0, count is 0.
    // Otherwise, sum over db=0 to floor(S/2), dc=0 to floor((S-2*db)/2) of (S - 2*db - 2*dc + 1).

    // Similarly for bad case 2 and 3.

    // Let me write a helper function to compute this sum.

    auto count_bad = [&](long long A, long long B, long long C, long long L) -> long long {
        // Count (da, db, dc) >= 0, da+db+dc <= L, such that A + da >= B + db + C + dc
        // i.e., da >= (B + C - A) + db + dc
        long long R = B + C - A;
        long long S = L - R;
        if (S < 0) return 0;
        // Sum over db=0 to floor(S/2), dc=0 to floor((S-2*db)/2) of (S - 2*db - 2*dc + 1)
        long long total = 0;
        for (long long db = 0; 2 * db <= S; db++) {
            long long max_dc = (S - 2 * db) / 2;
            // Sum_{dc=0}^{max_dc} (S - 2*db - 2*dc + 1)
            // = (max_dc + 1) * (S - 2*db + 1) - 2 * (max_dc * (max_dc + 1) / 2)
            // = (max_dc + 1) * (S - 2*db + 1) - max_dc * (max_dc + 1)
            // = (max_dc + 1) * (S - 2*db + 1 - max_dc)
            // = (max_dc + 1) * (S - 2*db + 1 - (S - 2*db)/2)
            // Let me just compute it directly.
            long long term = S - 2 * db + 1;
            // Sum of (term - 2*dc) for dc=0 to max_dc
            // = (max_dc+1)*term - 2*(max_dc*(max_dc+1)/2)
            // = (max_dc+1)*term - max_dc*(max_dc+1)
            // = (max_dc+1)*(term - max_dc)
            total += (max_dc + 1) * (term - max_dc);
        }
        return total;
    };

    long long total_ways = (l + 1) * (l + 2) * (l + 3) / 6;

    long long bad1 = count_bad(a, b, c, l);
    long long bad2 = count_bad(b, a, c, l);
    long long bad3 = count_bad(c, a, b, l);

    long long result = total_ways - bad1 - bad2 - bad3;

    cout << result << endl;

    return 0;
}
